import axios from 'axios';
import confetti from 'canvas-confetti';
import { useAuth } from '../context/AuthContext';
import KibaShield from '../components/KibaShield';
import Footer from '../components/Footer';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const EyeOpen = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M12 5C7 5 2.73 8.11 1 12.5C2.73 16.89 7 20 12 20C17 20 21.27 16.89 23 12.5C21.27 8.11 17 5 12 5Z" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx="12" cy="12.5" r="3.5" stroke="#0EA5E9" strokeWidth="2"/>
    <circle cx="12" cy="12.5" r="1.5" fill="#0EA5E9"/>
  </svg>
);

const EyeClosed = () => (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M2 2L22 22" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round"/>
    <path d="M6.71 6.71C4.56 8.08 2.9 10.11 2 12.5C3.73 16.89 8 20 13 20C15.11 20 17.07 19.32 18.66 18.18" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.88 4.13C10.57 4.05 11.28 4 12 4C17 4 21.27 7.11 23 11.5C22.47 12.87 21.69 14.09 20.72 15.12" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.76 9.76C9.29 10.23 9 10.88 9 11.6C9 13.14 10.35 14.4 12 14.4C12.76 14.4 13.45 14.12 13.96 13.66" stroke="#0EA5E9" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const Register = () => {
  const { login, darkMode } = useAuth();
  const navigate = useNavigate();
  const [fullName, setFullName] = useState('');
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [role, setRole] = useState('customer');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [pose, setPose] = useState(1);
  const [shieldState, setShieldState] = useState('idle');

  const passwordStrength = (pwd) => {
    if (pwd.length === 0) return null;
    if (pwd.length < 6) return { label: 'Too short', color: '#EF4444', width: '25%' };
    if (pwd.length < 8) return { label: 'Weak', color: '#F59E0B', width: '50%' };
    if (!/[A-Z]/.test(pwd) || !/[0-9]/.test(pwd)) return { label: 'Fair', color: '#F59E0B', width: '65%' };
    if (pwd.length >= 8 && /[A-Z]/.test(pwd) && /[0-9]/.test(pwd)) return { label: 'Strong', color: '#10B981', width: '100%' };
    return { label: 'Good', color: '#0EA5E9', width: '80%' };
  };

  const strength = passwordStrength(password);

  const handleIdentifierChange = (e) => {
    setIdentifier(e.target.value);
    if (e.target.value.length > 0) setPose(8);
    else setPose(1);
  };

  const handlePasswordFocus = () => setPose(9);
  const handlePasswordBlur = () => {
    if (identifier.length > 0) setPose(8);
    else setPose(1);
  };

  const handleTogglePassword = () => {
    setShowPassword(prev => !prev);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!fullName || !identifier || !password) {
      setError('Please fill in all fields');
      setPose(3);
      setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    if (password.length < 6) {
      setError('Password must be at least 6 characters long');
      setPose(3);
      setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    setLoading(true);
    setPose(7);
    setShieldState('idle');
    try {
      const res = await axios.post(`${API}/api/auth/register`, { fullName, identifier, password, role });
      setPose(2);
      setShieldState('success');
      confetti({
        particleCount: 200,
        spread: 100,
        origin: { y: 0.5 },
        colors: ['#10B981', '#0EA5E9', '#1E3A5F', '#F59E0B']
      });
      setTimeout(() => {
        login(res.data.user, res.data.token);
        const userRole = res.data.user.role;
        navigate(userRole === 'admin' ? '/admin' : userRole === 'staff' ? '/staff' : '/dashboard');
      }, 1500);
    } catch (err) {
      const msg = err.response?.data?.message || 'Something went wrong. Please try again.';
      setError(msg);
      if (msg.includes('already registered')) {
        setPose(3);
        setShieldState('warning');
      } else {
        setPose(4);
        setShieldState('danger');
      }
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
    } finally {
      setLoading(false);
    }
  };

  const inputStyle = {
    width: '100%',
    padding: '14px 48px 14px 16px',
    border: '2px solid #E2E8F0',
    borderRadius: '12px',
    fontSize: '15px',
    fontFamily: 'Inter, sans-serif',
    background: darkMode ? '#0F172A' : '#fff',
    color: darkMode ? '#F1F5F9' : '#1E293B',
    outline: 'none',
    boxSizing: 'border-box'
  };

  const normalInputStyle = {
    width: '100%',
    padding: '14px 16px',
    border: '2px solid #E2E8F0',
    borderRadius: '12px',
    fontSize: '15px',
    fontFamily: 'Inter, sans-serif',
    background: darkMode ? '#0F172A' : '#fff',
    color: darkMode ? '#F1F5F9' : '#1E293B',
    outline: 'none',
    boxSizing: 'border-box'
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F8FAFC' }}>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '32px 16px' }}>
        <div style={{ display: 'flex', gap: '56px', alignItems: 'center', width: '100%', maxWidth: '920px', flexWrap: 'wrap', justifyContent: 'center' }}>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '20px' }}>
            <KibaShield
              pose={pose}
              shieldState={shieldState}
              customLabel={loading ? 'Processing securely...' : null}
            />
            <div style={{ textAlign: 'center' }}>
              <h1 style={{ fontSize: '30px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', margin: 0 }}>
                KibaliGuard
              </h1>
              <p style={{ color: '#64748B', fontSize: '14px', marginTop: '6px' }}>
                Your data. Your rules. Your control.
              </p>
            </div>
          </div>

          <div style={{
            background: darkMode ? '#1E293B' : '#ffffff',
            borderRadius: '24px',
            padding: '44px 40px',
            boxShadow: '0 8px 48px rgba(30,58,95,0.13)',
            width: '100%',
            maxWidth: '420px'
          }}>
            <h2 style={{ fontSize: '26px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '6px' }}>
              Create account
            </h2>
            <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '32px' }}>
              Join KibaliGuard and take control of your data
            </p>

            {error && (
              <div style={{ background: '#FEF2F2', color: '#EF4444', border: '1px solid #FECACA', borderRadius: '12px', padding: '13px 16px', fontSize: '14px', fontWeight: 500, marginBottom: '20px' }}>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', fontWeight: 600, fontSize: '14px', color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '8px' }}>
                  Full name
                </label>
                <input
                  type="text"
                  placeholder="Enter your full name"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  style={normalInputStyle}
                />
              </div>

              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', fontWeight: 600, fontSize: '14px', color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '8px' }}>
                  Email or phone number
                </label>
                <input
                  type="text"
                  placeholder="e.g. your@gmail.com or 07XXXXXXXX"
                  value={identifier}
                  onChange={handleIdentifierChange}
                  style={normalInputStyle}
                />
              </div>

              <div style={{ marginBottom: '8px' }}>
                <label style={{ display: 'block', fontWeight: 600, fontSize: '14px', color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '8px' }}>
                  Password
                </label>
                <div style={{ position: 'relative' }}>
                  <input
                    type={showPassword ? 'text' : 'password'}
                    placeholder="Create a strong password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    onFocus={handlePasswordFocus}
                    onBlur={handlePasswordBlur}
                    style={inputStyle}
                  />
                  <button
                    type="button"
                    onClick={handleTogglePassword}
                    style={{
                      position: 'absolute',
                      right: '12px',
                      top: '50%',
                      transform: 'translateY(-50%)',
                      background: 'none',
                      border: 'none',
                      cursor: 'pointer',
                      padding: '4px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center'
                    }}
                    title={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? <EyeOpen /> : <EyeClosed />}
                  </button>
                </div>
              </div>

              {strength && (
                <div style={{ marginBottom: '20px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                    <span style={{ fontSize: '12px', color: '#64748B', fontWeight: 500 }}>Password strength</span>
                    <span style={{ fontSize: '12px', fontWeight: 700, color: strength.color }}>{strength.label}</span>
                  </div>
                  <div style={{ height: '4px', background: '#E2E8F0', borderRadius: '999px', overflow: 'hidden' }}>
                    <div style={{ height: '100%', width: strength.width, background: strength.color, borderRadius: '999px', transition: 'all 0.3s ease' }} />
                  </div>
                  {strength.label !== 'Strong' && (
                    <p style={{ fontSize: '11px', color: '#94A3B8', marginTop: '4px' }}>
                      Use at least 8 characters with an uppercase letter and a number for a strong password
                    </p>
                  )}
                </div>
              )}

              <div style={{ marginBottom: '28px' }}>
                <label style={{ display: 'block', fontWeight: 600, fontSize: '14px', color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '8px' }}>
                  Account type
                </label>
                <select
                  value={role}
                  onChange={(e) => setRole(e.target.value)}
                  style={normalInputStyle}
                >
                  <option value="customer">Customer / Job Applicant</option>
                  <option value="staff">Staff / HR Officer</option>
                  <option value="admin">Administrator</option>
                </select>
              </div>

              <button
                type="submit"
                disabled={loading}
                style={{
                  width: '100%',
                  padding: '15px',
                  background: loading ? '#0EA5E9' : '#1E3A5F',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '12px',
                  fontWeight: 700,
                  fontSize: '16px',
                  cursor: loading ? 'not-allowed' : 'pointer',
                  fontFamily: 'Inter, sans-serif',
                  marginBottom: '20px',
                  transition: 'all 0.3s',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '10px'
                }}
              >
                {loading ? (
                  <>
                    <span style={{ width: '18px', height: '18px', border: '3px solid rgba(255,255,255,0.3)', borderTop: '3px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'kibashield-spin 0.8s linear infinite' }} />
                    Creating your account...
                  </>
                ) : 'Create Account'}
              </button>
            </form>

            <div style={{ textAlign: 'center', fontSize: '14px', color: '#64748B' }}>
              Already have an account?{' '}
              <Link to="/login" style={{ color: '#0EA5E9', fontWeight: 700, textDecoration: 'none' }}>
                Sign in here
              </Link>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Register;
